import com.oracle.e1.common.OrchestrationAttributes;
import java.text.SimpleDateFormat;
import groovy.json.*;

HashMap<String, Object> main(OrchestrationAttributes orchAttr, HashMap inputMap)
{
HashMap<String, Object> returnMap = new HashMap<String, Object>();

String CreateOrderNumber = (String) inputMap.get("CreateOrderNumber");

BigDecimal CreateBUCheck = null;
String CreateBUCheck_str = (String)inputMap.get("CreateBUCheck");
if(CreateBUCheck_str != null && !CreateBUCheck_str.trim().isEmpty())
{
CreateBUCheck = new BigDecimal(CreateBUCheck_str);
}    

BigDecimal CreateBPCheck = null;
String CreateBPCheck_str = (String)inputMap.get("CreateBPCheck");
if(CreateBPCheck_str != null && !CreateBPCheck_str.trim().isEmpty())
{
CreateBPCheck = new BigDecimal(CreateBPCheck_str);
}      

BigDecimal CreateStatusCheck = null;
String CreateStatusCheck_str = (String)inputMap.get("CreateStatusCheck");
if(CreateStatusCheck_str != null && !CreateStatusCheck_str.trim().isEmpty())
{
CreateStatusCheck = new BigDecimal(CreateStatusCheck_str);
}    

String Status = "UNKNOWN";
String Action = "UNKNOWN";
String Errors = "";

if(CreateBUCheck==0) //BU check did NOT pass
{
Action = "ERROR";
Status = "FAILURE";
Errors = Errors + "Supplied Business Unit Does Not Exist or Is Not Available For Posting\n";    
}
if(CreateBPCheck==0) //BP check did NOT pass
{
Action = "ERROR";
Status = "FAILURE";
Errors = Errors + "Supplied Branch Plant Does Not Exist or Is Inactive\n"; 
}    
if(CreateStatusCheck==0) //Status check did NOT pass
{
Action = "ERROR";
Status = "FAILURE";
Errors = Errors + "Supplied Status is not valid\n"; 

}      
if(CreateOrderNumber!=null && !CreateOrderNumber.trim().isEmpty()) //If a value was returned it is safe to assume the record was Successfully Created
{
Action = "CREATE";
Status = "SUCCESS";

}

returnMap.put("Action", Action);        
returnMap.put("Status", Status);   
returnMap.put("Errors", Errors);   

return returnMap;
}
